(() => {
 const inputs = [...document.querySelectorAll('input')].map(i => ({label: i.getAttribute('aria-label'), ph: i.placeholder, val: i.value}));
 const statEls = [...document.querySelectorAll('button,[role="option"],[role="radio"],[role="listitem"]')].map(e=>e.textContent.trim()).filter(t=>/^stat/i.test(t)).slice(0,20);
 const matched = [...document.querySelectorAll('*')].filter(e=>e.children.length===0 && /Matched \d+\/\d+ options/.test(e.textContent)).map(e=>e.textContent);
 return {inputs, statEls, matched};
})()

(() => {
 const m = [...document.querySelectorAll('*')].find(e=>e.children.length===0 && /Matched \d+\/\d+ options/.test(e.textContent));
 let root = m; for (let i=0;i<10 && root && root.parentElement;i++) root = root.parentElement;
 const btns = root ? [...root.querySelectorAll('button')].map(b=>b.textContent.trim()).filter(Boolean) : null;
 return {matched: m && m.textContent, rootTag: root && root.tagName, rootClass: root && String(root.className).slice(0,120), items: btns && btns.slice(0,60), count: btns && btns.length};
})()

(() => {
 const all = [...document.querySelectorAll('*')];
 const stats = all.filter(e=>e.children.length===0 && e.textContent.trim()==='Stat').map(e=>({tag:e.tagName, cls:String(e.className).slice(0,60), parentCls:String(e.parentElement && e.parentElement.className).slice(0,60)}));
 const pickerish = [...new Set(all.map(e=>String(e.className)).filter(c=>/picker|Picker|viz/i.test(c)))].slice(0,20);
 const searchInput = all.filter(e=>e.tagName==='INPUT' && e.placeholder==='Search options').map(e=>({val:e.value, cls:String(e.className).slice(0,60)}));
 return {statsCount: stats.length, stats: stats.slice(0,5), pickerish, searchInput};
})()

(() => {
 const areas = [...document.querySelectorAll('textarea,[contenteditable="true"]')].map(e=>({tag:e.tagName, cls:String(e.className).slice(0,80), aria:e.getAttribute('aria-label'), val:(e.value||e.textContent||'').slice(0,80), ph:e.getAttribute('placeholder')}));
 return areas;
})()

(() => {
 const el = document.getElementById('auto-refresh-input');
 let n = el, chain = [];
 for (let i=0;i<6 && n;i++){ chain.push({tag:n.tagName, cls:String(n.className).slice(0,80)}); n = n.parentElement; }
 const labels = [...document.querySelectorAll('label,legend,h3,h4,div')].filter(e=>e.children.length===0 && /auto refresh|refresh interval/i.test(e.textContent)).map(e=>({tag:e.tagName, txt:e.textContent.trim().slice(0,60), html:e.tagName==='LABEL'?e.getAttribute('for'):null}));
 return {chain, labels};
})()

(() => {
 const sels = [...document.querySelectorAll('select')].map(s=>({id:s.id, aria:s.getAttribute('aria-label'), opts:[...s.options].map(o=>o.text).slice(0,12)}));
 const cbs = [...document.querySelectorAll('[role="combobox"]')].map(e=>({tag:e.tagName, aria:e.getAttribute('aria-label'), txt:e.textContent.trim().slice(0,40)}));
 const refEls = [...document.querySelectorAll('*')].filter(e=>e.children.length===0 && /refresh/i.test(e.textContent)).map(e=>({tag:e.tagName, txt:e.textContent.trim().slice(0,50)}));
 const inp = document.getElementById('auto-refresh-input');
 return {sels, cbs, refreshTexts: refEls.slice(0,25), inpHTML: inp ? inp.outerHTML.slice(0,300) : null, inpParentHTML: inp ? inp.parentElement.parentElement.parentElement.outerHTML.slice(0,600) : null};
})()
